refentry.refsect1:
&reftitle.description;

 trueusort
 arrayarray
 callablecallback



 Ordina array sul posto per valore, usando una
 funzione di confronto fornita dall'utente per determinare l'ordine.

&note.sort-unstable;
&note.no-key-association;

  &reftitle.examples;



    Esempio di usort


<?php
function cmp($a, $b)
{
    if ($a == $b) {
        return 0;
    }
    return ($a < $b) ? -1 : 1;
}

$a = array(3, 2, 5, 6, 1);

usort($a, "cmp");

foreach ($a as $key => $value) {
    echo "$key: $value\n";
}
?>


    &example.outputs;


0: 1
1: 2
2: 3
3: 5
4: 6




     L'operatore spaceship può essere usato per
     semplificare ulteriormente il confronto interno.



<?php
function cmp($a, $b)
{
    return $a <=> $b;
}

$a = array(3, 2, 5, 6, 1);

usort($a, "cmp");

foreach ($a as $key => $value) {
    echo "$key: $value\n";
}
?>







    Ovviamente in questo caso banale la funzione sort
    sarebbe più appropriata.






     Esempio di usort con un array multidimensionale



<?php
function cmp($a, $b)
{
    return strcmp($a["fruit"], $b["fruit"]);
}

$fruits[0]["fruit"] = "limoni";
$fruits[1]["fruit"] = "mele";
$fruits[2]["fruit"] = "uva";

usort($fruits, "cmp");

foreach ($fruits as $key => $value) {
    echo "\$fruits[$key]: " . $value["fruit"] . "\n";
}
?>


    &example.outputs;


$fruits[0]: limoni
$fruits[1]: mele
$fruits[2]: uva




     Quando si ordina un array multidimensionale, $a e
     $b contengono riferimenti al primo indice dell'array.







     Esempio di usort con un metodo di un oggetto



<?php
class TestObj {
    public string $name;

    function __construct($name)
    {
        $this->name = $name;
    }

    /* Questa è la funzione di confronto statica: */
    static function cmp_obj($a, $b)
    {
        return strtolower($a->name) <=> strtolower($b->name);
    }
}

$a[] = new TestObj("c");
$a[] = new TestObj("b");
$a[] = new TestObj("d");

usort($a, [TestObj::class, "cmp_obj"]);

foreach ($a as $item) {
    echo $item->name . "\n";
}
?>


    &example.outputs;


b
c
d





     Esempio di usort con una closure
     per ordinare un array multidimensionale



<?php
$array[0] = array('key_a' => 'z', 'key_b' => 'c');
$array[1] = array('key_a' => 'x', 'key_b' => 'b');
$array[2] = array('key_a' => 'y', 'key_b' => 'a');

function build_sorter($key) {
    return function ($a, $b) use ($key) {
        return strnatcmp($a[$key], $b[$key]);
    };
}

usort($array, build_sorter('key_b'));

foreach ($array as $item) {
    echo $item['key_a'] . ', ' . $item['key_b'] . "\n";
}
?>


    &example.outputs;


y, a
x, b
z, c





     Esempio di usort con l'operatore spaceship



     L'operatore spaceship consente di confrontare in modo semplice
     valori composti su più assi. L'esempio seguente ordina
     $people per cognome e poi, a parità di cognome,
     per nome.



<?php
$people[0] = ['first' => 'Adam', 'last' => 'West'];
$people[1] = ['first' => 'Alec', 'last' => 'Baldwin'];
$people[2] = ['first' => 'Adam', 'last' => 'Baldwin'];

function sorter(array $a, array $b) {
    return [$a['last'], $a['first']] <=> [$b['last'], $b['first']];
}

usort($people, 'sorter');

foreach ($people as $person) {
    print $person['last'] . ', ' . $person['first'] . PHP_EOL;
}
?>


    &example.outputs;


Baldwin, Adam
Baldwin, Alec
West, Adam
